package com.northstar.crm.service;import com.northstar.crm.domain.*;import com.northstar.crm.repo.PlanRepository;import com.northstar.crm.security.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;@Service public class PlanService {private final PlanRepository plans;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;public PlanService(PlanRepository p,ActorResolver a,AccessPolicy x,AuditService audit){plans=p;actors=a;access=x;this.audit=audit;}@Transactional(readOnly=true)public List<PlanDefinition> all(){actors.current();return plans.findAll().stream().sorted(Comparator.comparing(PlanDefinition::getMonthlyPrice)).toList();}@Transactional public void update(UUID id,BigDecimal price,int rate,int users){var actor=actors.current();access.requireAdmin(actor);if(price==null||price.signum()<0||price.scale()>2||rate<1||users<1)throw new IllegalArgumentException("Use positive limits and a fixed-precision price");var p=plans.findById(id).orElseThrow();var before="price="+p.getMonthlyPrice()+",rate="+p.getApiRateLimit()+",users="+p.getUserLimit();p.update(price,rate,users);audit.record(actor,"PLAN_SETTINGS_CHANGED","Plan",id,before,"price="+price+",rate="+rate+",users="+users,"platform admin");}}
